import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../providers/ai_provider.dart';
class AiMoodScreen extends StatefulWidget{const AiMoodScreen({super.key});@override State<AiMoodScreen> createState()=>_S();}
class _S extends State<AiMoodScreen>{final c=TextEditingController();String result='';bool loading=false;Future<void> go()async{setState(()=>loading=true);try{final r=await context.read<AiProvider>().classifyMood(c.text);result=r.detectedMood+'\n'+r.explanation+'\n\nأفلام: '+r.movies.join('، ')+'\nأنمي: '+r.anime.join('، ');}catch(e){result=e.toString();}if(mounted)setState(()=>loading=false);}@override void dispose(){c.dispose();super.dispose();}@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('حسب مزاجي')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:c,maxLines:3,decoration:const InputDecoration(hintText:'مثلاً: بدي شيء غامض ومشوق الليلة')),const SizedBox(height:12),ElevatedButton(onPressed:loading?null:go,child:const Text('حلل مزاجي')),if(loading)const Padding(padding:EdgeInsets.all(16),child:CircularProgressIndicator()),if(result.isNotEmpty)Expanded(child:SingleChildScrollView(child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Text(result)))))]));}}
